const ICON_MAP = new Map(CATEGORY_ICONS.map(i => [i.key, i]));

export function getCategoryIcon(key?: string | null): CategoryIconDef | undefined {
  return key ? ICON_MAP.get(key) : undefined;
}

// Renders a category icon by key. Returns `fallback` (default null) when the
// key is empty/unknown. Uses currentColor so callers control the color.
export default function CategoryIcon({
  icon,
  className = 'w-5 h-5',
  fallback = null,
}: {
  icon?: string | null;
  className?: string;
  fallback?: ReactNode;
}) {
  const def = getCategoryIcon(icon);
  if (!def) return <>{fallback}</>;
  return (
    <svg className={className} viewBox={def.viewBox} fill="none" stroke="currentColor" strokeWidth={def.strokeWidth} strokeLinecap="round" strokeLinejoin="round">
      {def.paths.map((d, i) => <path key={i} d={d} />)}
    </svg>
  );
}
